//! 📣️ Scoped ingress donates only admitted aliases to the background event lane.
use super::*;
use semio_framework_plugin_decl_emission::{ActionMeta,HostEvent};
type SourceScope=Option<(semio_framework_job::OriginalSourceBinding,(u64,u64))>;
fn claim_scope(scope:&mut SourceScope,pending:bool,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if (*scope).is_some_and(|(scope,decoder)|scope.matches(cx)&&cx.native_receiving_identity()==Some(decoder)){return Ok(true)}if pending{return Ok(false)}let binding=semio_framework_job::OriginalSourceBinding::borrow(cx);let bytes=2*std::mem::size_of::<Option<(semio_framework_job::OriginalSourceBinding,(u64,u64))>>();let mut done=None;semio_framework_job::admit_original_construction(cx,&mut done,semio_framework_job::OriginalConstructionDemand{items:1,copy_bytes:bytes,capacity_bytes:0,release_bytes:0,depth:1},|control|{let result=(||{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(||semio_framework_value::ValueError::invariant("original command scope requires its actual decoder recipient"))?);*scope=Some((binding,decoder));Ok(((),semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}))})();semio_framework_value::RetainedWorkOutcome{result,work:1}})?;Ok(false)}
impl<A:ArtifactApp,M:ReferenceSpaceMember+MemberFactory+Send+'static> VcsArtifactApp<A,M>{
 pub(crate) fn action_host_event_close_demands(&self,body:usize)->Result<semio_framework_value::RetirementDemand,semio_framework_value::ValueError>{if !self.host_events.action_delivery.terminal_is_empty(){return self.host_events.action_delivery.close_demands(body)}Ok(semio_framework_value::RetirementDemand{copy_bytes:2*std::mem::size_of::<Option<HostEvent>>()+4*std::mem::size_of::<bool>(),depth:1,..Default::default()})}
 pub(crate) fn close_action_host_events(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<(),semio_framework_job::OriginalTurnFailure>{if !self.host_events.action_delivery.terminal_is_empty(){self.host_events.action_delivery.close_step(cx)?;return Ok(())}let d=self.action_host_event_close_demands(cx.retained_grant().maximum_copy_bytes)?;cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|_|{if self.host_events.queue.is_empty(){self.host_events.delivering=false;self.host_events.reply=false;self.host_events.action_event_complete=false;self.host_events.action_event_removed=false;}else{*self.host_events.action_delivery.event=self.host_events.queue.pop_front();}semio_framework_value::RetainedWorkOutcome{result:Ok(semio_framework_value::RetainedCloneStep::Progress(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;Ok(())})}
 pub(crate) fn claim_original_host_event_scope(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{let pending=self.original_host_event_command.pending()||self.host_events.routes.delivering||!self.host_events.routes.delivery_is_empty();claim_scope(&mut self.original_host_event_scope,pending,cx)}
 pub(crate) fn original_host_event_close_demands(&self,body:usize)->Result<semio_framework_value::RetirementDemand,semio_framework_value::ValueError>{if self.original_host_event_command.pending(){return semio_framework_plugin_instance_dispatch::dispatch_runtime_command::original_typed_source_close_demands(&self.original_host_event_command,body)}if !self.host_events.routes.delivery_is_empty(){return self.host_events.routes.delivery_close_demands(body)}Ok(semio_framework_value::RetirementDemand{copy_bytes:std::mem::size_of::<(bool,bool,u64)>(),depth:1,..Default::default()})}
 pub(crate) fn close_original_host_event_source(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<semio_framework_value::RetainedCloneStep,semio_framework_job::OriginalTurnFailure>{if self.original_host_event_command.pending(){return semio_framework_plugin_instance_dispatch::dispatch_runtime_command::close_original_typed_source(&mut self.original_host_event_command,&mut self.tools.typed_operation_reservations,&mut self.host_events.host_event_operations,cx)}let before=cx.retained_progress();if !self.host_events.routes.delivery_is_empty(){self.host_events.routes.close_delivery(cx)?;}else{self.host_events.routes.finish_cancelled(cx)?;}Ok(semio_framework_value::RetainedCloneStep::Progress(semio_framework_plugin_ownership::bounded_ownership::original_lifecycle_delta(before,cx.retained_progress())?))}
 pub(crate) fn owns_original_command_scope(&self,cx:&semio_framework_job::StepContext<'_>)->bool{self.original_command_scope.is_some_and(|(scope,decoder)|scope.matches(cx)&&cx.native_receiving_identity()==Some(decoder))}
 pub(crate) fn owns_original_host_event_source(&self,cx:&semio_framework_job::StepContext<'_>)->bool{self.original_host_event_scope.is_some_and(|(scope,decoder)|scope.matches(cx)&&cx.native_receiving_identity()==Some(decoder))&&(self.original_host_event_command.pending()||self.host_events.routes.delivering||!self.host_events.routes.delivery_is_empty())}
 pub(crate) fn shared_command_source_pending(&self)->bool{self.host_events.delivering||!self.host_events.action_delivery.terminal_is_empty()||self.host_events.routes.cache_busy()||self.tools.original_tool_tag_capture.is_some()||self.tools.original_tool_tag_retirement.is_some()||self.tools.original_scrub_dispatch.is_some()||self.tools.original_press_settlement.is_some()||self.tools.original_typing_settlement.is_some()||self.tools.original_tool_follow.is_some()||self.original_typed_tag.is_some()||!self.original_typed_tag_close.is_empty()||self.original_typed_command.pending()||self.original_typing.pending()||self.original_emission.pending()}
 pub(crate) fn claim_original_command_scope(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{let pending=self.shared_command_source_pending();claim_scope(&mut self.original_command_scope,pending,cx)}
 pub(crate) fn capture_original_host_event_route(&mut self,meta:Option<&ActionMeta>,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{
  if !self.claim_original_command_scope(cx)?{return Ok(false)}
  if self.host_events.routes.delivering{return Ok(true)}let Some(meta)=meta.filter(|meta|meta.view_state.is_some())else{return Ok(true)};if self.tools.live_runtime_instance_id!=Some(meta.instance_id)||meta.actor.as_str()!=self.stores.store.local_actor_id().0.as_str(){return Err(semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvalidValue,"host event routing requires its actual mounted actor and instance").into())}self.host_events.routes.capture(meta,cx)
 }
}
